@pytest.fixture(scope="module")
def sections_dict(research_plan_content: Optional[str]) -> Dict[str, str]:
    """
    Parse the research plan into a dictionary of sections.

    Uses Markdown heading syntax (## or ###) to identify section boundaries.

    Returns:
        A dict mapping section titles to their content.
    """
    if research_plan_content is None:
        return {}

    sections: Dict[str, str] = {}
    current_section: Optional[str] = None
    current_lines: List[str] = []

    for line in research_plan_content.splitlines():
        # Detect Markdown headings (## or ###)
        heading_match = re.match(r'^(#{2,3})\s+(.+)$', line.strip())
        if heading_match:
            # Save previous section
            if current_section is not None:
                sections[current_section] = "\n".join(current_lines).strip()
            # Start new section
            current_section = heading_match.group(2).strip()
            current_lines = []
        else:
            if current_section is not None:
                current_lines.append(line)

    # Don't forget the last section
    if current_section is not None:
        sections[current_section] = "\n".join(current_lines).strip()

    logger.info(f"Parsed {len(sections)} sections from research plan")
    return sections

