class TestDocumentStructure:
    """Verify the physical structure and accessibility of the research plan."""

    def test_file_exists(self):
        """Ensure the research plan file is present at the expected path."""
        assert RESEARCH_PLAN_PATH.exists(), (
            f"Research plan file not found at {RESEARCH_PLAN_PATH}"
        )
        logger.info("File existence check passed")

    def test_file_not_empty(self, research_plan_content: Optional[str]):
        """Verify the file contains content."""
        assert research_plan_content is not None, "File content could not be loaded"
        assert len(research_plan_content.strip()) > 0, "File is empty"
        logger.info("File non-empty check passed")

    def test_required_sections_present(self, sections_dict: Dict[str, str]):
        """Check that all required sections are present in the document."""
        missing_sections = [
            section for section in REQUIRED_SECTIONS
            if not any(section.lower() in key.lower() for key in sections_dict.keys())
        ]
        assert not missing_sections, (
            f"Missing required sections: {missing_sections}. "
            f"Found sections: {list(sections_dict.keys())}"
        )
        logger.info(f"All {len(REQUIRED_SECTIONS)} required sections present")

    def test_no_empty_sections(self, sections_dict: Dict[str, str]):
        """Ensure no section is empty or contains only whitespace."""
        empty_sections = [
            name for name, content in sections_dict.items()
            if not content.strip()
        ]
        assert not empty_sections, f"Empty sections found: {empty_sections}"
        logger.info("No empty sections detected")

