class TestContentValidity:
    """Validate the semantic content and logical consistency of the plan."""

    def test_required_concepts_present(self, research_plan_content: Optional[str]):
        """Verify that key AI safety concepts are discussed in the document."""
        if research_plan_content is None:
            pytest.skip("No content to analyze")

        content_lower = research_plan_content.lower()
        missing_concepts = [
            concept for concept in REQUIRED_CONCEPTS
            if concept.lower() not in content_lower
        ]
        assert not missing_concepts, (
            f"Missing required concepts: {missing_concepts}"
        )
        logger.info(f"All {len(REQUIRED_CONCEPTS)} required concepts found")

    def test_methodology_has_detail(self, sections_dict: Dict[str, str]):
        """Check that the Methodology section has substantial content."""
        methodology_key = next(
            (key for key in sections_dict.keys() if "methodology" in key.lower()),
            None
        )
        if methodology_key is None:
            pytest.skip("Methodology section not found")

        methodology_content = sections_dict[methodology_key]
        # Expect at least 3 sentences or 100 characters
        sentence_count = len(re.findall(r'[.!?]+', methodology_content))
        assert sentence_count >= 3 or len(methodology_content) >= 100, (
            f"Methodology section too brief ({sentence_count} sentences, "
            f"{len(methodology_content)} chars)"
        )
        logger.info(f"Methodology section has adequate detail ({sentence_count} sentences)")

    def test_timeline_is_structured(self, sections_dict: Dict[str, str]):
        """Verify the Timeline section contains date-like patterns or milestones."""
        timeline_key = next(
            (key for key in sections_dict.keys() if "timeline" in key.lower()),
            None
        )
        if timeline_key is None:
            pytest.skip("Timeline section not found")

        timeline_content = sections_dict[timeline_key]
        # Look for patterns like "Q1 2024", "Month 1", "Phase 1", or dates
        has_milestones = bool(
            re.search(r'(Q[1-4]\s*\d{4}|Month\s+\d+|Phase\s+\d+|\d{4}-\d{2}-\d{2})', 
                      timeline_content, re.IGNORECASE)
        )
        assert has_milestones, "Timeline lacks structured milestones or dates"
        logger.info("Timeline contains structured milestones")

    def test_references_format(self, sections_dict: Dict[str, str]):
        """Check that references are present and in a recognizable format."""
        refs_key = next(
            (key for key in sections_dict.keys() if "reference" in key.lower()),
            None
        )
        if refs_key is None:
            pytest.skip("References section not found")

        refs_content = sections_dict[refs_key]
        # Check for common citation patterns: [1], (Author, Year), or numbered lists
        has_citations = bool(
            re.search(r'(\[\d+\]|\([A-Za-z]+,\s*\d{4}\)|\d+\.\s+[A-Za-z])', refs_content)
        )
        assert has_citations, "References section does not contain recognizable citations"
        logger.info("References section contains properly formatted citations")

