class TestDataIntegrity:
    """Test for robustness against malformed input and edge cases."""

    def test_no_placeholder_text(self, research_plan_content: Optional[str]):
        """Ensure the document does not contain common placeholder text."""
        if research_plan_content is None:
            pytest.skip("No content to analyze")

        placeholders = ["TODO", "FIXME", "INSERT", "PLACEHOLDER", "TBD"]
        found_placeholders = [
            ph for ph in placeholders if ph.lower() in research_plan_content.lower()
        ]
        assert not found_placeholders, (
            f"Placeholder text found: {found_placeholders}"
        )
        logger.info("No placeholder text detected")

    def test_consistent_heading_levels(self, research_plan_content: Optional[str]):
        """Verify that heading levels are used consistently (no jumps from ## to ####)."""
        if research_plan_content is None:
            pytest.skip("No content to analyze")

        heading_levels = []
        for line in research_plan_content.splitlines():
            match = re.match(r'^(#{1,6})\s', line)
            if match:
                heading_levels.append(len(match.group(1)))

        # Check for jumps of more than 1 level
        for i in range(1, len(heading_levels)):
            if heading_levels[i] > heading_levels[i-1] + 1:
                pytest.fail(
                    f"Heading level jump detected: from level {heading_levels[i-1]} "
                    f"to level {heading_levels[i]} at line {i+1}"
                )
        logger.info("Heading levels are consistent")

    def test_encoding_robustness(self):
        """Ensure the file can be read with UTF-8 encoding without errors."""
        try:
            with open(RESEARCH_PLAN_PATH, "r", encoding="utf-8") as f:
                f.read()
        except UnicodeDecodeError as e:
            pytest.fail(f"File contains invalid UTF-8: {e}")
        logger.info("UTF-8 encoding check passed")

    def test_line_length_warning(self, research_plan_content: Optional[str]):
        """
        Warn if any line exceeds 120 characters (common readability limit).
        This is a soft check; it does not fail the test.
        """
        if research_plan_content is None:
            pytest.skip("No content to analyze")

        long_lines = []
        for i, line in enumerate(research_plan_content.splitlines(), 1):
            if len(line) > 120:
                long_lines.append((i, len(line)))

        if long_lines:
            logger.warning(
                f"Found {len(long_lines)} lines exceeding 120 chars: "
                f"{long_lines[:5]}..."  # Show first 5
            )
        else:
            logger.info("All lines within 120-character limit")

