class TestCrossReferences:
    """Validate internal consistency and cross-references within the document."""

    def test_abstract_matches_conclusion(self, sections_dict: Dict[str, str]):
        """Check that the Abstract and Conclusion are not contradictory."""
        abstract_key = next(
            (key for key in sections_dict.keys() if "abstract" in key.lower()),
            None
        )
        conclusion_key = next(
            (key for key in sections_dict.keys() if "conclusion" in key.lower()),
            None
        )

        if abstract_key is None or conclusion_key is None:
            pytest.skip("Abstract or Conclusion section not found")

        abstract_text = sections_dict[abstract_key].lower()
        conclusion_text = sections_dict[conclusion_key].lower()

        # Check for contradictory keywords
        contradictions = [
            ("positive", "negative"),
            ("success", "failure"),
            ("feasible", "infeasible"),
        ]
        for pos, neg in contradictions:
            if pos in abstract_text and neg in conclusion_text:
                logger.warning(
                    f"Potential contradiction: Abstract mentions '{pos}' "
                    f"but Conclusion mentions '{neg}'"
                )
        logger.info("Abstract/Conclusion cross-reference check completed")

    def test_all_acronyms_defined(self, research_plan_content: Optional[str]):
        """
        Check that acronyms are defined on first use.
        This is a heuristic test looking for common AI acronyms.
        """
        if research_plan_content is None:
            pytest.skip("No content to analyze")

        common_acronyms = ["RLHF", "AI", "ML", "NLP", "LLM", "AGI", "CNN", "RNN"]
        undefined_acronyms = []

        for acronym in common_acronyms:
            # Find first occurrence
            first_occurrence = research_plan_content.find(acronym)
            if first_occurrence == -1:
                continue

            # Check if the acronym appears in parentheses after its full form
            # within the preceding 200 characters
            preceding_text = research_plan_content[
                max(0, first_occurrence - 200):first_occurrence
            ]
            # Look for pattern: "Full Form (ACRONYM)"
            full_form_pattern = re.compile(
                r'\b\w+\s+\w+\s*\(?' + re.escape(acronym) + r'\)?',
                re.IGNORECASE
            )
            if not full_form_pattern.search(preceding_text):
                undefined_acronyms.append(acronym)

        if undefined_acronyms:
            logger.warning(
                f"Potentially undefined acronyms: {undefined_acronyms}"
            )
        else:
            logger.info("All common acronyms appear to be defined")

